def seed_payroll_schedules(apps, schema_editor):
    """ينشئ **نسخةً أعلى** لكل لائحةٍ قائمة: إسرائيل v2 وفلسطين v3.

    **idempotent ولا يمسّ النسخَ القائمة** (قرار #274): يُنسخ كلُّ سطرٍ حرفاً —
    بما فيه `period_overrides` و`needs_review` — ثم يُضاف سطرُ الرواتب الجديد
    في آخر الترتيب. وسطرا 102 والـביטוח لا يختلفان إلا في `cadence`.

    **والوسمُ هو حارسُ التكرار**: سنةٌ لها نسخةٌ بوسم هذه الهجرة لا تُنسخ ثانيةً،
    وإلا صار التشغيلُ الثاني v3 لإسرائيل وv4 لفلسطين.
    """
    DeadlineSchedule = apps.get_model("accounting_office", "DeadlineSchedule")
    DeadlineRule = apps.get_model("accounting_office", "DeadlineRule")
    for tax_system, note, extra_rule in (
        ("IL", IL_VERSION_NOTE, IL_SEMIANNUAL_RULE),
        ("PS", PS_VERSION_NOTE, PS_ANNUAL_RULE),
    ):
        years = (
            DeadlineSchedule.objects
            .filter(tax_system=tax_system)
            .values_list("year", flat=True)
            .distinct()
            .order_by("year")
        )
        for year in years:
            if DeadlineSchedule.objects.filter(
                tax_system=tax_system, year=year, note=note,
            ).exists():
                continue
            current = (
                DeadlineSchedule.objects
                .filter(tax_system=tax_system, year=year)
                .order_by("-version")
                .first()
            )
            if current is None:
                continue
            target = DeadlineSchedule.objects.create(
                tax_system=tax_system,
                year=year,
                version=current.version + 1,
                source_url=current.source_url,
                published_on=PUBLISHED_ON,
                rest_day_policy=current.rest_day_policy,
                authority_closed_days=list(current.authority_closed_days or []),
                note=note,
            )
            source_rules = list(current.rules.order_by("position", "id"))
            for rule in source_rules:
                cadence = rule.cadence
                if (
                    tax_system == "IL"
                    and rule.code in IL_SERVICE_CADENCE_CODES
                ):
                    cadence = "service"
                DeadlineRule.objects.create(
                    schedule=target,
                    code=rule.code,
                    name=rule.name,
                    service_code=rule.service_code,
                    cadence=cadence,
                    rule_kind=rule.rule_kind,
                    rule_day=rule.rule_day,
                    rule_month=rule.rule_month,
                    conditions=rule.conditions,
                    is_generated=rule.is_generated,
                    electronic_extension_days=rule.electronic_extension_days,
                    period_overrides=rule.period_overrides,
                    needs_review=rule.needs_review,
                    source_url=rule.source_url,
                    position=rule.position,
                    event_kind=rule.event_kind,
                )
            DeadlineRule.objects.create(
                schedule=target,
                position=len(source_rules),
                **extra_rule,
            )


def unseed_payroll_schedules(apps, schema_editor):
    """عكسٌ يحذف **النسخ التي أنشأتها هذه الهجرة وحدها** — بوسمها لا بأرقامها.

    ولا يمرّ في الإنتاج بعد أن تُنشأ التزامات: `Obligation.rule` على `PROTECT`،
    فحذفُ نسخةٍ تشير إليها التزاماتٌ يرفع `ProtectedError` ولا يمحو شيئاً — وهو
    المقصود: التاريخُ لا يُمحى (قرار #255). صالحٌ في قاعدةٍ بعد الهجرة قبل التوليد.
    """
    DeadlineSchedule = apps.get_model("accounting_office", "DeadlineSchedule")
    DeadlineSchedule.objects.filter(tax_system="IL", note=IL_VERSION_NOTE).delete()
    DeadlineSchedule.objects.filter(tax_system="PS", note=PS_VERSION_NOTE).delete()


def seed_payroll_document_items(apps, schema_editor):
    """يزرع بندَي الرواتب الشهريين لكل نظام — **idempotent** ولا يمسّ صفّاً قائماً."""
    PlatformDocumentItem = apps.get_model("accounting_office", "PlatformDocumentItem")
    for tax_system, rows in PAYROLL_DOCUMENT_ITEMS.items():
        for code, name, status, position in rows:
            PlatformDocumentItem.objects.get_or_create(
                tax_system=tax_system,
                code=code,
                defaults={
                    "name": name,
                    "cadence": "monthly",
                    "service_codes": ["payroll"],
                    "card_conditions": {},
                    "default_status": status,
                    "sort_order": position,
                },
            )


def unseed_payroll_document_items(apps, schema_editor):
    """عكسٌ يحذف **أكواد البذرة الأربعة وحدها** — لا بنداً أضافه المكتب."""
    PlatformDocumentItem = apps.get_model("accounting_office", "PlatformDocumentItem")
    for tax_system, code in _PAYROLL_ITEM_CODES:
        PlatformDocumentItem.objects.filter(
            tax_system=tax_system, code=code,
        ).delete()


